insert into public.demo_seeds (project_id, snapshot, booking, bookings, library)
select p.id, p.snapshot, to_jsonb(b), (select jsonb_agg(to_jsonb(all_b) order by all_b.id) from public.equipment_bookings all_b where all_b.project_id = p.id), $library$[]$library$::jsonb from public.projects p join public.equipment_bookings b on b.id = '00000000-0000-4000-8000-000000000251' where p.id = '00000000-0000-4000-8000-000000000002'
on conflict (project_id) do update set snapshot = excluded.snapshot, booking = excluded.booking, bookings = excluded.bookings, library = excluded.library;

