on conflict (project_id) do update set snapshot = excluded.snapshot, booking = excluded.booking, bookings = excluded.bookings, library = excluded.library;

-- The project starts with the starter library and the starter watch list.
select public.seed_library(d.project_id, d.library) from public.demo_seeds d where d.project_id = '00000000-0000-4000-8000-000000010010';
select public.seed_watch_rules('00000000-0000-4000-8000-000000010010');

-- In the pool of copies, free until a visitor claims it (claim_copy); seeding again leaves a held copy held.
insert into public.copy_pool (project_id) values ('00000000-0000-4000-8000-000000010010') on conflict (project_id) do nothing;

